import BN from "bn.js";
import {
  Identity,
  IDENTITY_MAX_UNLOCK_DELAY,
  fqnToAddress,
} from "verus-typescript-primitives";
import {
  isIdentityLockedAtHeight,
  normalizeIdentityLockUpdate,
  validateIdentityLockTransition,
} from "../identity/identityLocks";
import { TEST_ID_3, VERUSTEST_I_ADDR } from "./fixtures/verusid";

// Generated by scripts/audit-identity-lock-oracle.js: actual, unmodified daemon
// method bodies are compiled as C++, retaining native uint32 arithmetic. The
// fixture records the extracted source hashes and every assumption of the shell.
const oracle = require("./fixtures/local-upload/identity-lock-oracle.json");

interface LockState {
  flags: number;
  unlockAfter: number;
}

interface LockCase {
  name: string;
  mode: "normalize" | "validate" | "lock" | "unlock";
  current: LockState;
  requested: LockState;
  height: number;
  expiry: number;
  scope: "modern-sdk" | "daemon-arithmetic-only";
  context?: { chain: string; identityId: string; upgradeHeight?: number };
  daemon: LockState & {
    oldLockedAtHeight: boolean;
    newLockedAtHeight: boolean;
    invalidMutation: boolean;
    oldOverride: boolean;
    newOverride: boolean;
  };
}

const cases = oracle.cases as LockCase[];
const varrr = fqnToAddress("vARRR.vrsc.@");
const exemptIds = new Set([
  "iSXF8KbbvpHDWBm4zHxeA4n7uc1LsfR15X",
  "i4UxDzYtNR5oeGEEVritXuzAKjKzoVgiPK",
  "i5nQeKAWmxaXdNYv36qLQzz6XV8gZEqbaV",
]);

function identity(state: LockState, fixture: LockCase): Identity {
  const result = Identity.fromJson(TEST_ID_3.identity);
  result.flags = new BN(state.flags);
  result.unlockAfter = new BN(state.unlockAfter);
  // The extracted C++ shell likewise provides the identity ID symbolically.
  // This isolates lock predicates; it does not claim address/name validation.
  if (fixture.context?.identityId !== undefined) {
    result.getIdentityAddress = () => fixture.context!.identityId;
  }
  return result;
}

function context(fixture: LockCase) {
  return {
    chainId:
      fixture.context?.chain === "vARRR.vrsc.@" ? varrr : VERUSTEST_I_ADDR,
    nextBlockHeight: fixture.height,
  };
}

function needsUnavailableUpgrade(state: LockState, fixture: LockCase): boolean {
  return (
    fixture.context?.chain === "vARRR.vrsc.@" &&
    fixture.height < 67000 &&
    exemptIds.has(fixture.context.identityId) &&
    state.unlockAfter > 800000 &&
    (state.flags & (2 | 0x8000)) === 0
  );
}

describe("compiled daemon lock oracle", () => {
  test.each(
    cases.filter((value) => value.mode === "normalize" || value.mode === "lock")
  )("normalization preserves native daemon arithmetic: $name", (fixture) => {
    const current = identity(fixture.current, fixture);
    const next = identity(fixture.requested, fixture);
    normalizeIdentityLockUpdate(
      current,
      next,
      new BN(fixture.height),
      new BN(fixture.expiry)
    );
    expect({
      flags: next.flags.toNumber(),
      unlockAfter: next.unlockAfter.toNumber(),
    }).toEqual({
      flags: fixture.daemon.flags,
      unlockAfter: fixture.daemon.unlockAfter,
    });
    expect(current.flags.toNumber()).toBe(fixture.current.flags);
    expect(current.unlockAfter.toNumber()).toBe(fixture.current.unlockAfter);
  });

  test.each(cases.filter((value) => value.scope === "modern-sdk"))(
    "lock state and consensus acceptance match the daemon: $name",
    (fixture) => {
      const current = identity(fixture.current, fixture);
      const next = identity(fixture.daemon, fixture);
      const trustedContext = context(fixture);
      for (const [value, state, expected] of [
        [current, fixture.current, fixture.daemon.oldLockedAtHeight],
        [next, fixture.daemon, fixture.daemon.newLockedAtHeight],
      ] as const) {
        const check = () => isIdentityLockedAtHeight(value, trustedContext);
        if (needsUnavailableUpgrade(state, fixture)) {
          expect(check).toThrow(/unavailable upgrade activation state/);
        } else {
          expect(check()).toBe(expected);
        }
      }
      const check = () =>
        validateIdentityLockTransition(
          current,
          next,
          trustedContext,
          fixture.expiry
        );
      // The daemon can read an earlier on-chain upgrade. Until that state is
      // available, the client must reject a transition whose result depends on it.
      const unknownUpgrade =
        !next.isRevoked() &&
        (needsUnavailableUpgrade(fixture.current, fixture) ||
          needsUnavailableUpgrade(fixture.daemon, fixture));
      if (unknownUpgrade) {
        expect(check).toThrow(/unavailable upgrade activation state/);
      } else if (fixture.daemon.invalidMutation) {
        expect(check).toThrow();
      } else {
        expect(check).not.toThrow();
      }
    }
  );

  test("includes distinct active and inactive historical upgrade outcomes", () => {
    const matching = cases.filter(
      (value) =>
        value.name.startsWith("override/upgrade-") &&
        value.mode === "validate" &&
        value.current.flags === 0 &&
        value.current.unlockAfter === 900000
    );
    expect(
      matching.some(
        (value) => !value.daemon.oldOverride && value.daemon.oldLockedAtHeight
      )
    ).toBe(true);
    expect(
      matching.some(
        (value) => value.daemon.oldOverride && !value.daemon.oldLockedAtHeight
      )
    ).toBe(true);
  });

  test("exported mutable primitives constants cannot change daemon normalization", () => {
    const fixture = cases.find(
      (value) => value.name === "direct-lock/11563201"
    )!;
    expect(fixture).toBeDefined();
    const before = IDENTITY_MAX_UNLOCK_DELAY.clone();
    try {
      IDENTITY_MAX_UNLOCK_DELAY.iaddn(1000);
      const current = identity(fixture.current, fixture);
      const next = identity(fixture.requested, fixture);
      normalizeIdentityLockUpdate(
        current,
        next,
        new BN(fixture.height),
        new BN(fixture.expiry)
      );
      expect(next.unlockAfter.toNumber()).toBe(fixture.daemon.unlockAfter);
    } finally {
      IDENTITY_MAX_UNLOCK_DELAY.isub(IDENTITY_MAX_UNLOCK_DELAY.sub(before));
    }
  });
});
